package Digest::file;use strict;use warnings;use Exporter ();use Carp qw(croak);use Digest ();our$VERSION="1.20";our@ISA=qw(Exporter);our@EXPORT_OK=qw(digest_file_ctx digest_file digest_file_hex digest_file_base64);sub digest_file_ctx {my$file=shift;croak("No digest algorithm specified")unless @_;open(my$fh,"<",$file)|| croak("Can't open '$file': $!");binmode($fh);my$ctx=Digest->new(@_);$ctx->addfile($fh);close($fh);return$ctx}sub digest_file {digest_file_ctx(@_)->digest}sub digest_file_hex {digest_file_ctx(@_)->hexdigest}sub digest_file_base64 {digest_file_ctx(@_)->b64digest}1;